insert into waytara.instrument_enum_values (enum_ref, code, label, notes)
values
  ('inverter_state', '0', 'Standby', 'DISCREPANCY: V1 (hybrid map) and Deye''s V133 doc disagree at code 5 — V1 says ''activating'', V133 says ''Turn off''. These are opposite meanings. Confirm against this unit''s LCD before relying on code 5 for anything user-facing.'),
  ('inverter_state', '1', 'Self-check', null),
  ('inverter_state', '2', 'Normal', null),
  ('inverter_state', '3', 'Alarm', null),
  ('inverter_state', '4', 'Fault (V1) / Failure (V133)', null),
  ('inverter_state', '5', 'Activating (V1) / Turn off (V133)', null),
  ('device_type', '0x0200', 'String/hybrid inverter family (observed on this unit)', 'Not a small enumerated list — a hex identifier used to select the profile file at runtime. Only one value has been observed; other device_type codes exist across Deye''s product range but aren''t catalogued here.'),
  ('battery_type', '0', 'Lead-acid', 'Confirmed [OK].'),
  ('battery_type', '1', 'Lithium', null),
  ('batt_control_mode', '0', 'By voltage', 'Confirmed [OK]. Decides which threshold set (voltage vs SOC) is active elsewhere in the settings.'),
  ('batt_control_mode', '1', 'By SOC', null),
  ('batt_control_mode', '2', 'No battery', null),
  ('gen_port_function', '0', 'Generator input', 'Confirmed [OK]. Gates the whole generator settings panel.'),
  ('gen_port_function', '1', 'Smart-load output', null),
  ('gen_port_function', '2', 'Micro-inverter input', null),
  ('export_limit_mode', '0', 'Sell to grid', 'Confirmed [OK]. The old map mistakenly typed this register as watts — it''s an enum, not a power value.'),
  ('export_limit_mode', '1', 'Limit via built-in CT', null),
  ('export_limit_mode', '2', 'Limit via external meter', null),
  ('grid_frequency_setting', '0', '50 Hz', 'Confirmed [OK]. Regulated setting — requires the confirmation-before-write step, plus a write-log entry.'),
  ('grid_frequency_setting', '1', '60 Hz', null),
  ('bms_protocol', '0', 'General CAN (only value observed on this unit)', 'Full list NOT available — the reference map only notes ''enum, list in V110 register 223'', a document we don''t have. Only code 0 has been sampled. Do not build a full picker until the complete list is sourced.'),
  ('grid_standard', '1', 'INMETRO', 'Full list sourced from Deye''s V133 doc (more complete than the hybrid map, which only said ''[1,21], see V110 appendix 4'' with no list). Code 19 repeats ''EN50549'' (same as code 2) verbatim in Deye''s own document — likely a copy-paste error in their source, not a transcription mistake here; confirm on the unit''s LCD before treating 19 as a distinct standard. Valid range in the hybrid map was [1,21] but V133 goes up to 22 — recheck the range too. Regulated setting: requires confirmation-before-write plus a write-log entry.'),
  ('grid_standard', '2', 'EN50549', null),
  ('grid_standard', '3', 'EN50438', null),
  ('grid_standard', '4', 'IEC61727', null),
  ('grid_standard', '5', 'CUSTOM', null),
  ('grid_standard', '6', 'VDE_AR_N_4105', null),
  ('grid_standard', '7', 'UTE_C15_712_1', null),
  ('grid_standard', '8', 'RD_1699', null),
  ('grid_standard', '9', 'CEI_0_21', null),
  ('grid_standard', '10', 'G98_G99', null),
  ('grid_standard', '11', 'AS4777', null),
  ('grid_standard', '12', 'NB/T 32004', null),
  ('grid_standard', '13', 'AS4777.2 Australia A', null),
  ('grid_standard', '14', 'AS4777.2 Australia B', null),
  ('grid_standard', '15', 'AS4777.2 Australia C', null),
  ('grid_standard', '16', 'AS4777.2 New Zealand', null),
  ('grid_standard', '17', 'MEA', null),
  ('grid_standard', '18', 'PEA', null),
  ('grid_standard', '19', 'EN50549 (repeated — see note)', null),
  ('grid_standard', '20', 'VDE4105', null),
  ('grid_standard', '21', 'R25', null),
  ('grid_standard', '22', 'CEI-016', null)
